// CU39 - Interpreta la frase dictada y devuelve la consulta estructurada que espera el ERP.
// Entrada (body del webhook): { texto, fechaReferencia, sucursales[], productos[], metricas[] }
// Salida: { metrica, agrupacion, fechaInicio, fechaFin, sucursalId, productoId, soloCriticos, limite }
// Se puede reemplazar por un nodo de IA siempre que devuelva el mismo JSON; el backend
// valida todo contra su catálogo y nunca arma SQL con este texto.
const body = $input.first().json.body || {};
const NUM = { dos: 2, tres: 3, cuatro: 4, cinco: 5, seis: 6, siete: 7, ocho: 8, nueve: 9, diez: 10,
  once: 11, doce: 12, quince: 15, veinte: 20, treinta: 30 };
const norm = (s) => ' ' + String(s || '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase()
  .replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter(Boolean)
  .map((w) => (NUM[w] !== undefined ? String(NUM[w]) : w)).join(' ') + ' ';
const t = norm(body.texto);
const tiene = (...claves) => claves.some((k) => t.includes(' ' + k));

const ref = String(body.fechaReferencia || new Date().toISOString().slice(0, 10));
const [Y, M, D] = ref.split('-').map(Number);
const fecha = (y, m, d) => new Date(Date.UTC(y, m - 1, d));
const hoy = fecha(Y, M, D);
const mas = (f, dias) => new Date(f.getTime() + dias * 86400000);
const finDeMes = (y, m) => fecha(y, m + 1, 0);
const iso = (f) => f.toISOString().slice(0, 10);

// 1. Métrica: términos informales a entidades del ERP ("lo que vendimos" -> VENTAS)
let metrica = null;
if (tiene('por cobrar', 'cxc', 'cobranza', 'cartera', 'deuda', 'nos deben', 'morosos')) metrica = 'CUENTAS_POR_COBRAR';
else if (tiene('compra', 'proveedor', 'adquisicion')) metrica = 'COMPRAS';
else if (tiene('kardex', 'movimiento', 'entradas', 'salidas')) metrica = 'MOVIMIENTOS_KARDEX';
else if (tiene('stock', 'inventario', 'existencia', 'agotad', 'reponer', 'reposicion')) metrica = 'STOCK';
else if (tiene('mas vendid', 'productos vendidos', 'articulos vendidos', 'que productos', 'que articulos')) metrica = 'PRODUCTOS_VENDIDOS';
else if (tiene('venta', 'vend', 'factur', 'ingreso', 'recaud', 'ganamos', 'top', 'ranking', 'mejores')) metrica = 'VENTAS';
if (!metrica) return [{ json: { metrica: null } }];

// 2. Rango de fechas ("el mes pasado" -> mes calendario anterior)
const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto',
  'septiembre', 'octubre', 'noviembre', 'diciembre'];
let rango = null;
let m;
if ((m = t.match(/ (?:ultimos|ultimas) (\d{1,3}) (dias|semanas|meses|anos) /) ||
         t.match(/ (\d{1,3}) (?:ultimos|ultimas) (dias|semanas|meses|anos) /))) {
  const n = Number(m[1]);
  let inicio;
  if (m[2] === 'dias') inicio = mas(hoy, -(n - 1));
  else if (m[2] === 'semanas') inicio = mas(hoy, -(7 * n) + 1);
  else if (m[2] === 'meses') inicio = mas(fecha(Y, M - n, D), 1);
  else inicio = mas(fecha(Y - n, M, D), 1);
  rango = [inicio, hoy];
} else if ((m = t.match(new RegExp(' (' + MESES.join('|') + ')(?: (?:de|del) (\\d{4}))? ')))) {
  const mes = MESES.indexOf(m[1]) + 1;
  const anio = m[2] ? Number(m[2]) : (mes > M ? Y - 1 : Y);
  rango = [fecha(anio, mes, 1), finDeMes(anio, mes)];
} else if (tiene('anteayer')) rango = [mas(hoy, -2), mas(hoy, -2)];
else if (tiene('ayer')) rango = [mas(hoy, -1), mas(hoy, -1)];
else if (tiene('hoy', 'del dia', 'en el dia')) rango = [hoy, hoy];
else if (tiene('semana pasada', 'ultima semana', 'semana anterior')) {
  const lunes = mas(hoy, -((hoy.getUTCDay() + 6) % 7) - 7);
  rango = [lunes, mas(lunes, 6)];
} else if (tiene('esta semana', 'semana actual')) rango = [mas(hoy, -((hoy.getUTCDay() + 6) % 7)), hoy];
else if (tiene('mes pasado', 'ultimo mes', 'mes anterior')) rango = [fecha(Y, M - 1, 1), finDeMes(Y, M - 1)];
else if (tiene('este mes', 'mes actual', 'va del mes', 'en el mes')) rango = [fecha(Y, M, 1), hoy];
else if (tiene('ano pasado', 'ultimo ano', 'ano anterior', 'gestion pasada', 'gestion anterior')) rango = [fecha(Y - 1, 1, 1), fecha(Y - 1, 12, 31)];
else if (tiene('este ano', 'ano actual', 'va del ano', 'esta gestion')) rango = [fecha(Y, 1, 1), hoy];
else if ((m = t.match(/ (?:en|del|de|el) (?:ano )?(20\d{2}) /))) rango = [fecha(Number(m[1]), 1, 1), fecha(Number(m[1]), 12, 31)];

// 3. Agrupación
const reglas = [
  ['DIA', ['por dia', 'diari', 'cada dia']], ['MES', ['por mes', 'mensual', 'cada mes']],
  ['SUCURSAL', ['por sucursal', 'cada sucursal']], ['CLIENTE', ['por cliente', 'cada cliente']],
  ['VENDEDOR', ['por vendedor', 'por cajero', 'cada vendedor']], ['PRODUCTO', ['por producto', 'por articulo', 'cada producto']],
  ['CATEGORIA', ['por categoria', 'cada categoria']], ['PROVEEDOR', ['por proveedor', 'cada proveedor']],
  ['TIPO', ['por tipo']], ['ESTADO', ['por estado']]];
let agrupacion = (reglas.find(([, claves]) => tiene(...claves)) || [null])[0];
if (!agrupacion && tiene('evolucion', 'tendencia', 'historico', 'comportamiento')) {
  agrupacion = rango && (rango[1] - rango[0]) / 86400000 <= 62 ? 'DIA' : 'MES';
}
if (!agrupacion) {
  const plurales = [['SUCURSAL', ['sucursales']], ['CLIENTE', ['clientes']], ['VENDEDOR', ['vendedores', 'cajeros']],
    ['CATEGORIA', ['categorias']], ['PROVEEDOR', ['proveedores']], ['PRODUCTO', ['productos', 'articulos']]];
  agrupacion = (plurales.find(([, claves]) => tiene(...claves)) || [null])[0];
}

// 4. Sucursal y producto: cada palabra pesa menos cuantas más entidades la comparten
const VACIAS = new Set(['sucursal', 'de', 'del', 'la', 'las', 'el', 'los', 'y', 'en', 'con', 'para', 'por', 'calle', 'av', 'esq', 'the', 'asus']);
const buscar = (entidades, alias) => {
  const palabras = entidades.map((e) => new Set(norm(e.nombre + ' ' + (e[alias] || '')).trim().split(' ')
    .filter((p) => p.length >= 3 && !VACIAS.has(p))));
  const frecuencia = {};
  palabras.forEach((ps) => ps.forEach((p) => { frecuencia[p] = (frecuencia[p] || 0) + 1; }));
  let mejor = null, mejorPuntaje = 0, segundo = 0;
  entidades.forEach((e, i) => {
    let puntaje = 0;
    palabras[i].forEach((p) => { if (t.includes(' ' + p + ' ')) puntaje += 1 / frecuencia[p]; });
    if (puntaje > mejorPuntaje) { segundo = mejorPuntaje; mejorPuntaje = puntaje; mejor = e.id; }
    else if (puntaje > segundo) segundo = puntaje;
  });
  return mejorPuntaje >= 0.5 && mejorPuntaje > segundo ? mejor : null;
};
const catalogo = Object.fromEntries((body.metricas || []).map((x) => [x.codigo, x]));
let productoId = buscar(body.productos || [], 'codigo');
if (metrica === 'VENTAS' && (productoId || agrupacion === 'PRODUCTO' || agrupacion === 'CATEGORIA')) metrica = 'PRODUCTOS_VENDIDOS';
const def = catalogo[metrica] || {};
if (!def.admiteProducto) productoId = null;
if (!agrupacion && productoId) agrupacion = metrica === 'STOCK' ? 'SUCURSAL' : metrica === 'PRODUCTOS_VENDIDOS' ? 'NINGUNA' : null;
if (agrupacion && def.agrupaciones && !def.agrupaciones.includes(agrupacion)) agrupacion = null;

const criticos = def.admiteCriticos && (metrica === 'STOCK'
  ? tiene('bajo minimo', 'bajo el minimo', 'debajo del minimo', 'critico', 'agotad', 'reponer', 'reposicion')
  : tiene('vencid', 'mora', 'morosos', 'atrasad'));

// 5. Límite ("top 5", "los 10 mejores")
let limite = null;
if ((m = t.match(/ (?:top|los|las|primeros|primeras|mejores) (\d{1,3}) (?!ultim|dia|semana|mes|ano)/) ||
         t.match(/ (\d{1,3}) (?:productos|articulos|clientes|proveedores|vendedores|mejores|primeros) /))) {
  const n = Number(m[1]);
  if (n >= 1 && n <= 100) limite = n;
}

const usaFechas = def.usaFechas !== false;
return [{
  json: {
    metrica,
    agrupacion,
    fechaInicio: usaFechas && rango ? iso(rango[0]) : null,
    fechaFin: usaFechas && rango ? iso(rango[1]) : null,
    sucursalId: buscar(body.sucursales || [], 'ciudad'),
    productoId,
    soloCriticos: criticos ? true : null,
    limite
  }
}];
